<script setup lang="ts">
const db=useSupabaseClient(),route=useRoute(),busy=ref(true),error=ref(''),rows=ref<any[]>([]),schoolName=ref('')
onMounted(async()=>{const {data:{user}}=await db.auth.getUser();if(!user){await navigateTo('/login');return}const r=await db.from('school_memberships').select('school_id,role,schools(name)').eq('user_id',user.id);if(r.error){error.value=r.error.message;busy.value=false;return}const id=typeof route.query.school==='string'?route.query.school:'';const m=(r.data||[]).find(x=>x.school_id===id&&['school_admin','teacher'].includes(x.role));if(!m){error.value='You do not have access to this school.';busy.value=false;return}schoolName.value=(m.schools as any)?.name||'School';const s=await db.from('school_memberships').select('user_id,role').eq('school_id',id).limit(500);rows.value=s.data||[];error.value=s.error?.message||'';busy.value=false})
</script>
<template><div class="page"><div class="shell admin-section"><NuxtLink to="/school/dashboard">← School Dashboard</NuxtLink><h1>{{schoolName}} — Staff</h1><p class="notice">School memberships only. Staff invitations and approval management will be added in a future phase.</p><p v-if="busy">Loading…</p><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="!busy&&!error" class="card"><h2>Members ({{rows.length}})</h2><div v-for="m in rows" :key="m.user_id" class="data-row"><span>{{m.role==='school_admin'?'School Administrator':'Teacher'}}</span><small>Account {{m.user_id.slice(0,8)}}…</small></div><p v-if="!rows.length">No members found.</p></div></div></div></template>
